{"content":"* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'Inter', -apple-system, sans-serif;
  background: #0a0a1a;
  color: #e8e8f0;
  min-height: 100vh;
  overflow-x: hidden;
}

#bgCanvas {
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  z-index: 0;
  opacity: 0.4;
}

.app-container {
  position: relative;
  z-index: 1;
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.5rem 3rem;
}

.header {
  text-align: center;
  margin-bottom: 2rem;
}

.header h1 {
  font-size: 2.4rem;
  font-weight: 700;
  background: linear-gradient(135deg, #ff6b6b, #ffa94d, #ffd43b, #69db7c, #74c0fc, #b197fc, #da77f2);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  letter-spacing: -0.02em;
}

.subtitle {
  color: #9090a8;
  font-size: 1.05rem;
  margin-top: 0.4rem;
  font-weight: 300;
}

.steps-nav {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.step-btn {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  color: #9090a8;
  padding: 0.55rem 1.2rem;
  border-radius: 999px;
  font-size: 0.88rem;
  font-family: inherit;
  cursor: pointer;
  transition: all 0.3s ease;
  backdrop-filter: blur(10px);
}

.step-btn:hover {
  background: rgba(255,255,255,0.1);
  color: #c8c8d8;
}

.step-btn.active {
  background: rgba(255,255,255,0.15);
  color: #fff;
  border-color: rgba(255,255,255,0.25);
  box-shadow: 0 0 20px rgba(180,160,255,0.15);
}

.content-area {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.2rem;
}

.main-canvas {
  width: 100%;
  aspect-ratio: 16/9;
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,0.08);
  background: rgba(10,10,30,0.6);
  backdrop-filter: blur(20px);
}

.info-card {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 1.5rem;
  backdrop-filter: blur(20px);
}

.info-card h2 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 0.6rem;
  color: #fff;
}

.info-card p {
  font-size: 0.95rem;
  line-height: 1.65;
  color: #b0b0c8;
  font-weight: 300;
}

.detail {
  margin-top: 0.8rem;
  padding: 0.8rem 1rem;
  background: rgba(255,255,255,0.04);
  border-radius: 10px;
  border-left: 3px solid #74c0fc;
  font-size: 0.85rem;
  color: #9090a8;
  font-style: italic;
}

.progress-bar {
  margin-top: 1.2rem;
  height: 4px;
  background: rgba(255,255,255,0.08);
  border-radius: 999px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #74c0fc, #b197fc);
  border-radius: 999px;
  transition: width 0.5s ease;
}

.nav-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 1rem;
  gap: 0.8rem;
}

.nav-btn {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  color: #d0d0e0;
  padding: 0.5rem 1.2rem;
  border-radius: 999px;
  font-size: 0.88rem;
  font-family: inherit;
  cursor: pointer;
  transition: all 0.25s ease;
}

.nav-btn:hover:not(:disabled) {
  background: rgba(255,255,255,0.15);
  transform: translateY(-1px);
}

.nav-btn:disabled {
  opacity: 0.3;
  cursor: default;
}

.step-counter {
  font-size: 0.85rem;
  color: #7878a0;
  font-weight: 500;
}

@media (min-width: 640px) {
  .content-area {
    grid-template-columns: 1fr 320px;
  }
  .header h1 { font-size: 3rem; }
}
","path":"rainbow-app/style.css"}

