{"content":"const canvas = document.getElementById('rainbowCanvas');
const ctx = canvas.getContext('2d');
const infoTitle = document.getElementById('infoTitle');
const infoText = document.getElementById('infoText');
const detailText = document.getElementById('detailText');
const progressFill = document.getElementById('progressFill');
const stepCounter = document.getElementById('stepCounter');
const prevBtn = document.getElementById('prevBtn');
const nextBtn = document.getElementById('nextBtn');

const steps = [
  {
    title: 'Step 1: White Sunlight',
    text: 'Sunlight appears white, but it\'s actually a mixture of all visible colors — every wavelength from violet to red. Each color has a different wavelength, which turns out to be the key to everything that follows.',
    detail: 'Fun fact: Red light has the longest wavelength (~750 nm), while violet has the shortest (~380 nm). All these colors travel together through space, but water has a way of separating them.'
  },
  {
    title: 'Step 2: Refraction',
    text: 'When sunlight enters a raindrop, it slows down because water is denser than air. This change in speed causes the light to bend — a process called refraction. The droplet acts like a tiny prism.',
    detail: 'The refractive index of water is about 1.33, meaning light travels roughly 33% slower in water than in a vacuum. This bending is what sets everything else in motion.'
  },
  {
    title: 'Step 3: Dispersion',
    text: 'Here\'s the magic: water bends different colors by different amounts. Violet bends the most, red the least. This wavelength-dependent refraction — called dispersion — is what splits white light into a spectrum.',
    detail: 'This is also why you can use a glass prism to make a rainbow. The angle difference between violet and red is about 2° inside the water.'
  },
  {
    title: 'Step 4: Internal Reflection',
    text: 'After dispersing inside the droplet, the light reaches the back surface. Most of it passes through, but a significant portion reflects off the inner surface — like a curved mirror — sending it back toward the front of the droplet.',
    detail: 'For the primary rainbow, there is exactly one internal reflection. A secondary (fainter) rainbow forms when light reflects twice inside the droplet, which reverses the color order.'
  },
  {
    title: 'Step 5: Your Eye Collects the Light',
    text: 'The dispersed, reflected light exits the droplet and refracts again — further separating colors. All the droplets at ~42° from the anti-solar point send concentrated red light to your eye, while those at ~40° send violet. Millions of droplets combine to paint the rainbow.',
    detail: 'Every observer sees their own unique rainbow — made by different droplets. If two people stand together, they literally see different rainbows. That\'s why rainbows are so personal.'
  }
];

let currentStep = 0;
let animTime = 0;
let droplets = [];
let sunRay = 0;
let particles = [];

function init() {
  resize();
  window.addEventListener('resize', resize);
  createDroplets();

  document.querySelectorAll('.step-btn').forEach(btn => {
    btn.addEventListener('click', () => goToStep(parseInt(btn.dataset.step)));
  });
  prevBtn.addEventListener('click', () => goToStep(currentStep - 1));
  nextBtn.addEventListener('click', () => goToStep(currentStep + 1));

  goToStep(0);
  requestAnimationFrame(animate);
}

function resize() {
  const rect = canvas.parentElement.getBoundingClientRect();
  const w = rect.width;
  const h = w * 0.5625;
  canvas.width = w * devicePixelRatio;
  canvas.height = h * devicePixelRatio;
  canvas.style.width = w + 'px';
  canvas.style.height = h + 'px';
  ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
}

function createDroplets() {
  droplets = [];
  for (let i = 0; i < 60; i++) {
    droplets.push({
      x: Math.random(),
      y: 0.3 + Math.random() * 0.6,
      r: 0.008 + Math.random() * 0.015,
      phase: Math.random() * Math.PI * 2,
      speed: 0.3 + Math.random() * 0.5
    });
  }
}

function goToStep(n) {
  if (n < 0 || n >= steps.length) return;
  currentStep = n;
  document.querySelectorAll('.step-btn').forEach((btn, i) => {
    btn.classList.toggle('active', i === n);
  });
  infoTitle.textContent = steps[n].title;
  infoText.textContent = steps[n].text;
  detailText.textContent = steps[n].detail;
  progressFill.style.width = ((n + 1) / steps.length * 100) + '%';
  stepCounter.textContent = (n + 1) + ' / ' + steps.length;
  prevBtn.disabled = n === 0;
  nextBtn.disabled = n === steps.length - 1;
  particles = [];
}

function drawDroplet(cx, cy, radius, opacity) {
  ctx.save();
  ctx.globalAlpha = opacity;

  // Droplet body
  const grad = ctx.createRadialGradient(cx - radius * 0.3, cy - radius * 0.3, 0, cx, cy, radius);
  grad.addColorStop(0, 'rgba(180, 210, 255, 0.15)');
  grad.addColorStop(0.7, 'rgba(140, 180, 240, 0.08)');
  grad.addColorStop(1, 'rgba(100, 150, 220, 0.02)');
  ctx.beginPath();
  ctx.arc(cx, cy, radius, 0, Math.PI * 2);
  ctx.fillStyle = grad;
  ctx.fill();

  // Rim highlight
  ctx.beginPath();
  ctx.arc(cx, cy, radius * 0.95, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(200, 220, 255, 0.12)';
  ctx.lineWidth = 0.5;
  ctx.stroke();

  ctx.restore();
}

function drawSun(cx, cy) {
  ctx.save();

  // Sun glow
  const sunGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, 60);
  sunGrad.addColorStop(0, 'rgba(255, 240, 180, 0.8)');
  sunGrad.addColorStop(0.3, 'rgba(255, 200, 100, 0.3)');
  sunGrad.addColorStop(1, 'rgba(255, 180, 80, 0)');
  ctx.fillStyle = sunGrad;
  ctx.beginPath();
  ctx.arc(cx, cy, 60, 0, Math.PI * 2);
  ctx.fill();

  // Sun core
  const coreGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, 18);
  coreGrad.addColorStop(0, '#fffbe6');
  coreGrad.addColorStop(1, '#ffd43b');
  ctx.beginPath();
  ctx.arc(cx, cy, 18, 0, Math.PI * 2);
  ctx.fillStyle = coreGrad;
  ctx.fill();

  ctx.restore();
}

function drawSunRays(cx, cy) {
  const colors = [
    'rgba(255, 100, 100, 0.7)',
    'rgba(255, 160, 60, 0.7)',
    'rgba(255, 210, 60, 0.7)',
    'rgba(100, 220, 120, 0.7)',
    'rgba(80, 160, 255, 0.7)',
    'rgba(120, 100, 255, 0.7)',
    'rgba(200, 80, 220, 0.7)'
  ];

  const dropX = cx * 0.55;
  const dropY = cy * 0.5;

  for (let i = 0; i < 7; i++) {
    const progress = Math.min(1, (animTime * 0.3 + i * 0.08) % 1.2);
    const startX = cx + 18;
    const endX = dropX - 15;
    const sx = startX + (endX - startX) * Math.min(1, progress * 1.2);
    const alpha = Math.max(0, 1 - Math.abs(progress - 0.7) * 2);

    ctx.beginPath();
    ctx.moveTo(sx, cy);
    ctx.lineTo(sx, cy);
    ctx.strokeStyle = colors[i].replace('0.7', alpha.toFixed(2));
    ctx.lineWidth = 2.5;
    ctx.stroke();

    // Continue to droplet
    if (progress > 0.5) {
      const rp = (progress - 0.5) * 2;
      const midX = dropX - 15;
      const midY = cy + (dropY - cy) * 0.3;
      const endX2 = dropX - 15;
      const endY2 = dropY;
      const ex = midX + (endX2 - midX) * Math.min(1, rp * 1.3);
      const ey = midY + (endY2 - midY) * Math.min(1, rp * 1.3);

      ctx.beginPath();
      ctx.moveTo(midX, midY);
      ctx.quadraticCurveTo(midX, midY, ex, ey);
      ctx.strokeStyle = colors[i].replace('0.7', (alpha * 0.7).toFixed(2));
      ctx.lineWidth = 2;
      ctx.stroke();
    }
  }
}

function drawRefractionPath(cx, cy) {
  const dropX = cx * 0.55;
  const dropY = cy * 0.5;
  const dropR = Math.min(cx, cy) * 0.18;

  const colors = ['#ff6b6b', '#ffa94d', '#ffd43b', '#69db7c', '#74c0fc', '#b197fc', '#da77f2'];
  const angles = [-0.15, -0.1, -0.05, 0, 0.05, 0.1, 0.15];

  // Incoming white light beam
  ctx.beginPath();
  ctx.moveTo(0, cy);
  ctx.lineTo(dropX - dropR * 0.85, dropY);
  ctx.strokeStyle = 'rgba(255,255,255,0.15)';
  ctx.lineWidth = 3;
  ctx.stroke();

  // Sun rays
  drawSunRays(cx, cy);

  // Inside droplet - dispersed rays
  const entranceX = dropX - dropR * 0.85;
  const entranceY = dropY;

  colors.forEach((color, i) => {
    const exitX = dropX + dropR * Math.cos(angles[i] + Math.PI * 0.5);
    const exitY = dropY - dropR * Math.abs(Math.sin(angles[i] + Math.PI * 0.5));

    // Inside path (dispersed)
    ctx.beginPath();
    ctx.moveTo(entranceX, entranceY);
    ctx.quadraticCurveTo(
      dropX + 10, dropY + 30,
      dropX, dropY + dropR * 0.7
    );
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.4;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Outgoing path
    ctx.beginPath();
    ctx.moveTo(dropX, dropY + dropR * 0.7);
    ctx.lineTo(dropX + dropR * 0.3, dropY + dropR * 1.5);
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.25;
    ctx.lineWidth = 1.2;
    ctx.stroke();
  });

  // Droplet outline
  ctx.beginPath();
  ctx.arc(dropX, dropY, dropR, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(180, 210, 255, 0.25)';
  ctx.lineWidth = 1.5;
  ctx.stroke();

  // Highlight on droplet
  ctx.beginPath();
  ctx.arc(dropX, dropY, dropR * 0.9, -Math.PI * 0.6, Math.PI * 0.3);
  ctx.strokeStyle = 'rgba(255,255,255,0.15)';
  ctx.lineWidth = 1;
  ctx.stroke();
}

function drawRainbowArc(cx, cy) {
  const baseR = Math.min(cx, cy) * 0.35;

  // Multiple arcs at different angles
  const bands = [
    { color: 'rgba(255, 80, 80, 0.35)', r: baseR },
    { color: 'rgba(255, 160, 60, 0.35)', r: baseR * 0.97 },
    { color: 'rgba(255, 220, 60, 0.35)', r: baseR * 0.94 },
    { color: 'rgba(100, 220, 120, 0.35)', r: baseR * 0.91 },
    { color: 'rgba(80, 160, 255, 0.35)', r: baseR * 0.88 },
    { color: 'rgba(120, 100, 255, 0.35)', r: baseR * 0.85 },
    { color: 'rgba(180, 80, 220, 0.35)', r: baseR * 0.82 }
  ];

  bands.forEach((band, i) => {
    const pulse = Math.sin(animTime * 0.8 + i * 0.5) * 0.05;
    const r = band.r * (1 + pulse);

    // Glow
    ctx.beginPath();
    ctx.arc(cx, cy * 0.8, r, Math.PI * 1.1, Math.PI * 1.9);
    ctx.strokeStyle = band.color;
    ctx.lineWidth = 12;
    ctx.globalAlpha = 0.15;
    ctx.stroke();

    // Main band
    ctx.beginPath();
    ctx.arc(cx, cy * 0.8, r, Math.PI * 1.1, Math.PI * 1.9);
    ctx.strokeStyle = band.color;
    ctx.lineWidth = 6;
    ctx.globalAlpha = 0.35;
    ctx.stroke();
  });

  // Anti-solar point
  ctx.beginPath();
  ctx.arc(cx * 1.6, cy * 0.8, 4, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.globalAlpha = 1;
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.4)';
  ctx.font = '11px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('Anti-solar point', cx * 1.6, cy * 0.8 + 20);

  // Angle arc
  const angle = baseR * 0.42;
  ctx.beginPath();
  ctx.moveTo(cx * 1.6, cy * 0.8);
  ctx.arc(cx * 1.6, cy * 0.8, angle, Math.PI, Math.PI * 1.5);
  ctx.strokeStyle = 'rgba(255,255,255,0.2)';
  ctx.lineWidth = 1;
  ctx.setLineDash([4, 4]);
  ctx.stroke();
  ctx.setLineDash([]);
}

function drawSingleDropletDemo(cx, cy, w, h) {
  const dropX = w * 0.5;
  const dropY = h * 0.5;
  const dropR = Math.min(w, h) * 0.2;
  const colors = ['#ff6b6b', '#ffa94d', '#ffd43b', '#69db7c', '#74c0fc', '#b197fc', '#da77f2'];

  // Big droplet
  const grad = ctx.createRadialGradient(dropX - dropR * 0.3, dropY - dropR * 0.3, 0, dropX, dropY, dropR);
  grad.addColorStop(0, 'rgba(200, 220, 255, 0.12)');
  grad.addColorStop(1, 'rgba(140, 180, 240, 0.03)');
  ctx.beginPath();
  ctx.arc(dropX, dropY, dropR, 0, Math.PI * 2);
  ctx.fillStyle = grad;
  ctx.fill();

  ctx.beginPath();
  ctx.arc(dropX, dropY, dropR, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(180, 210, 255, 0.3)';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Incoming light
  ctx.beginPath();
  ctx.moveTo(0, dropY);
  ctx.lineTo(dropX - dropR, dropY);
  ctx.strokeStyle = 'rgba(255,255,255,0.3)';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Arrow
  ctx.beginPath();
  ctx.moveTo(30, dropY - 5);
  ctx.lineTo(30, dropY + 5);
  ctx.lineTo(38, dropY);
  ctx.fillStyle = 'rgba(255,255,255,0.4)';
  ctx.fill();

  // Dispersed rays going out
  colors.forEach((color, i) => {
    const exitAngle = -Math.PI * 0.15 + i * 0.04;
    const ex = dropX + dropR * 1.5;
    const ey = dropY + exitAngle * dropR;

    ctx.beginPath();
    ctx.moveTo(dropX + dropR * 0.5, dropY - dropR * 0.3 + i * dropR * 0.12);
    ctx.quadraticCurveTo(
      dropX + dropR * 0.8, dropY + dropR * 0.5,
      ex, ey
    );
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.globalAlpha = 0.6;
    ctx.stroke();
  });

  // Labels
  ctx.globalAlpha = 1;
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.font = '12px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('Incoming', w * 0.08, dropY - 15);
  ctx.fillText('Dispersion', w * 0.65, h - 20);

  // Angle markers
  ctx.beginPath();
  ctx.arc(dropX - dropR, dropY, 15, 0, Math.PI);
  ctx.strokeStyle = 'rgba(255,255,255,0.2)';
  ctx.lineWidth = 1;
  ctx.stroke();
}

function drawReflectionPath(cx, cy, w, h) {
  const dropX = w * 0.5;
  const dropY = h * 0.45;
  const dropR = Math.min(w, h) * 0.22;
  const colors = ['#ff6b6b', '#ffa94d', '#ffd43b', '#69db7c', '#74c0fc', '#b197fc', '#da77f2'];

  // Droplet
  const grad = ctx.createRadialGradient(dropX - dropR * 0.3, dropY - dropR * 0.3, 0, dropX, dropY, dropR);
  grad.addColorStop(0, 'rgba(200, 220, 255, 0.1)');
  grad.addColorStop(1, 'rgba(140, 180, 240, 0.02)');
  ctx.beginPath();
  ctx.arc(dropX, dropY, dropR, 0, Math.PI * 2);
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.beginPath();
  ctx.arc(dropX, dropY, dropR, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(180, 210, 255, 0.25)';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Light enters left
  ctx.beginPath();
  ctx.moveTo(0, dropY);
  ctx.lineTo(dropX - dropR, dropY);
  ctx.strokeStyle = 'rgba(255,255,255,0.3)';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Refracted inside - converging
  colors.forEach((color, i) => {
    const startY = dropY - dropR * 0.1 + i * dropR * 0.04;
    const midY = dropY + dropR * 0.6 + Math.sin(i * 0.8) * dropR * 0.1;
    const endY = dropY + dropR * 0.15 + i * dropR * 0.1;

    ctx.beginPath();
    ctx.moveTo(dropX - dropR * 0.85, startY);
    ctx.quadraticCurveTo(dropX, midY, dropX, endY);
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.8;
    ctx.globalAlpha = 0.5;
    ctx.stroke();
  });

  // Reflection at back
  ctx.beginPath();
  ctx.moveTo(dropX, dropY + dropR * 0.5);
  ctx.quadraticCurveTo(dropX, dropY - dropR * 0.5, dropX, dropY - dropR * 0.3);
  ctx.strokeStyle = 'rgba(180, 210, 255, 0.3)';
  ctx.lineWidth = 1;
  ctx.globalAlpha = 1;
  ctx.stroke();

  // Reflected out bottom-left
  colors.forEach((color, i) => {
    const startX = dropX;
    const startY = dropY - dropR * 0.15 - i * dropR * 0.1;
    const endX = dropX - dropR * 1.2;
    const endY = dropY + dropR * 0.3 - i * dropR * 0.15;

    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.quadraticCurveTo(dropX - dropR * 0.5, startY + dropR * 0.3, endX, endY);
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.globalAlpha = 0.4;
