{"content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Aurora — Interactive Space Explorer</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
:root{
  --bg:#08081a;--surface:rgba(255,255,255,.04);--surface-hover:rgba(255,255,255,.08);
  --border:rgba(255,255,255,.08);--text:#e4e4f0;--text-dim:#7a7a9e;
  --accent:#7c6aef;--accent-glow:rgba(124,106,239,.25);--green:#34d399;
  --blue:#60a5fa;--pink:#f472b6;--orange:#fb923c;--cyan:#22d3ee;
}
html{font-size:16px}
body{font-family:'Inter',system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;overflow-x:hidden;position:relative}

/* Stars background */
#stars{position:fixed;top:0;left:0;width:100%;height:100%;z-index:0;pointer-events:none}

/* Aurora canvas */
#aurora{position:fixed;top:0;left:0;width:100%;height:100%;z-index:0;pointer-events:none;opacity:.3}

/* Main content */
.main{position:relative;z-index:1;max-width:1200px;margin:0 auto;padding:2rem 1.5rem 4rem}

/* Header */
.header{text-align:center;padding:3rem 0 2rem}
.header h1{font-family:'Space Grotesk',sans-serif;font-size:3.2rem;font-weight:700;background:linear-gradient(135deg,#c4b5fd,#818cf8,#7c3aed,#a855f7);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;letter-spacing:-.02em;margin-bottom:.5rem}
.header p{color:var(--text-dim);font-size:1.05rem;font-weight:300;max-width:500px;margin:0 auto}

/* Nav tabs */
.tabs{display:flex;justify-content:center;gap:.5rem;margin-bottom:2rem;flex-wrap:wrap}
.tab{background:var(--surface);border:1px solid var(--border);color:var(--text-dim);padding:.6rem 1.4rem;border-radius:999px;font-size:.875rem;font-family:inherit;cursor:pointer;transition:all .3s ease;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
.tab:hover{background:var(--surface-hover);color:var(--text)}
.tab.active{background:rgba(124,106,239,.15);color:#c4b5fd;border-color:rgba(124,106,239,.3);box-shadow:0 0 30px rgba(124,106,239,.12)}

/* Content area */
.content{display:grid;gap:1.5rem;grid-template-columns:1fr}
@media(min-width:800px){.content{grid-template-columns:1.6fr 1fr}}

/* Panels */
.panel{background:rgba(255,255,255,.03);border:1px solid var(--border);border-radius:20px;backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);overflow:hidden;transition:border-color .3s,box-shadow .3s}
.panel:hover{border-color:rgba(255,255,255,.12)}
.panel-header{padding:1.25rem 1.5rem 0;border-bottom:1px solid var(--border)}
.panel-header h2{font-family:'Space Grotesk',sans-serif;font-size:1.25rem;font-weight:600;display:flex;align-items:center;gap:.5rem}
.panel-body{padding:1.5rem}

/* Canvas container */
#viewCanvas{display:block;width:100%;border-radius:0 0 20px 20px}

/* Stats cards */
.stat-card{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:1rem 1.1rem;margin-bottom:.75rem;transition:all .25s ease}
.stat-card:hover{background:var(--surface-hover);transform:translateX(2px)}
.stat-label{font-size:.75rem;color:var(--text-dim);text-transform:uppercase;letter-spacing:.06em;font-weight:500;margin-bottom:.35rem}
.stat-value{font-family:'Space Grotesk',sans-serif;font-size:1.5rem;font-weight:700}
.stat-bar{height:3px;border-radius:999px;margin-top:.5rem;overflow:hidden}
.stat-bar-fill{height:100%;border-radius:999px;transition:width .6s ease}

/* Planet cards */
.planet-card{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:1.1rem 1.2rem;display:flex;align-items:center;gap:1rem;margin-bottom:.6rem;cursor:pointer;transition:all .3s ease;position:relative;overflow:hidden}
.planet-card:hover{background:var(--surface-hover);border-color:rgba(255,255,255,.15);transform:translateX(3px)}
.planet-card.selected{border-color:var(--accent);box-shadow:0 0 24px var(--accent-glow)}
.planet-card.selected::before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--accent);border-radius:0 3px 3px 0}
.planet-icon{width:40px;height:40px;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:1.3rem;flex-shrink:0}
.planet-info{flex:1;min-width:0}
.planet-name{font-weight:600;font-size:.9rem;margin-bottom:.15rem}
.planet-type{font-size:.75rem;color:var(--text-dim)}
.planet-dist{font-family:'Space Grotesk',sans-serif;font-size:.85rem;font-weight:600;color:var(--text-dim)}

/* Detail view */
.detail-section{margin-bottom:1rem}
.detail-section h3{font-size:.8rem;text-transform:uppercase;letter-spacing:.06em;color:var(--text-dim);margin-bottom:.5rem;font-weight:600}
.detail-section p{font-size:.875rem;line-height:1.65;color:#b0b0cc}

/* Quick stats */
.qs-grid{display:grid;grid-template-columns:1fr 1fr;gap:.5rem}
.qs{background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:.7rem;text-align:center}
.qs-val{font-family:'Space Grotesk',sans-serif;font-size:1.1rem;font-weight:700;margin-bottom:.15rem}
.qs-label{font-size:.65rem;color:var(--text-dim);text-transform:uppercase;letter-spacing:.05em}

/* Navigation */
.nav-row{display:flex;align-items:center;gap:.5rem;margin-top:1rem}
.nav-btn{background:var(--surface);border:1px solid var(--border);color:var(--text-dim);padding:.5rem 1rem;border-radius:999px;font-size:.8rem;font-family:inherit;cursor:pointer;transition:all .25s ease;display:flex;align-items:center;gap:.3rem}
.nav-btn:hover:not(:disabled){background:var(--surface-hover);color:var(--text);transform:translateY(-1px)}
.nav-btn:disabled{opacity:.25;cursor:default}
.nav-btn.primary{background:rgba(124,106,239,.15);border-color:rgba(124,106,239,.3);color:#c4b5fd}
.nav-btn.primary:hover{background:rgba(124,106,239,.25)}
.page-indicator{font-size:.8rem;color:var(--text-dim);margin:0 auto}

/* Scrollbar */
.panel-body::-webkit-scrollbar{width:4px}
.panel-body::-webkit-scrollbar-track{background:transparent}
.panel-body::-webkit-scrollbar-thumb{background:rgba(255,255,255,.1);border-radius:999px}

/* Responsive */
@media(max-width:599px){
  .header h1{font-size:2.2rem}
  .main{padding:1rem 1rem 3rem}
}

/* Animations */
@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
.fade-up{animation:fadeUp .5s ease both}
.fade-up-d1{animation-delay:.1s}.fade-up-d2{animation-delay:.2s}.fade-up-d3{animation-delay:.3s}
.fade-up-d4{animation-delay:.4s}

/* Loading shimmer */
@keyframes shimmer{0%{background-position:-200% 0}100%{background-position:200% 0}}
.shimmer{background:linear-gradient(90deg,var(--surface) 25%,rgba(255,255,255,.06) 50%,var(--surface) 75%);background-size:200% 100%;animation:shimmer 1.5s infinite}
</style>
</head>
<body>
<canvas id="stars"></canvas>
<canvas id="aurora"></canvas>

<div class="main">
  <header class="header fade-up">
    <h1>✦ Aurora Explorer</h1>
    <p>Journey through the cosmos. Click on planets to explore details of our solar system.</p>
  </header>

  <nav class="tabs fade-up fade-up-d1">
    <button class="tab active" data-tab="explore">🔭 Explore</button>
    <button class="tab" data-tab="planets">🪐 Planets</button>
    <button class="tab" data-tab="stats">📊 Stats</button>
  </nav>

  <div class="content fade-up fade-up-d2">
    <!-- Main view panel -->
    <div class="panel">
      <div class="panel-header"><h2 id="viewTitle">🌌 Deep Space</h2></div>
      <div class="panel-body" style="padding:.5rem">
        <canvas id="viewCanvas" height="460"></canvas>
      </div>
    </div>

    <!-- Side panel -->
    <div class="panel" id="sidePanel">
      <div class="panel-body" id="sideContent" style="padding:1rem"></div>
    </div>
  </div>
</div>

<script>
// Stars background
const starsCanvas=document.getElementById('stars');
const starsCtx=starsCanvas.getContext('2d');
const AURORA_SPEED=1.5;

let W,H,viewW,viewH,dpr;
let stars=[],nebulae=[];
let time=0;
let activeTab='explore';
let selectedPlanet=null;
let viewMode='free'; // free, planet, ring, star
let planetData={name:'',radius:0,orbit:0,color:'#fff',speed:0,moons:0,type:''};
let particles=[];
let mouse={x:0,y:0};
let transitionAlpha=0;

function resize(){
  dpr=Math.min(window.devicePixelRatio||1,2);
  W=innerWidth;H=innerHeight;
  starsCanvas.width=W*dpr;starsCanvas.height=H*dpr;
  starsCtx.setTransform(dpr,0,0,dpr,0,0);

  const cv=document.getElementById('viewCanvas');
  const rect=cv.parentElement.getBoundingClientRect();
  viewW=rect.width;viewH=460;
  cv.width=viewW*dpr;cv.height=viewH*dpr;
  cv.style.width=viewW+'px';cv.style.height=viewH+'px';
}
window.addEventListener('resize',resize);
resize();

// Create stars
function initStars(){
  stars=[];nebulae=[];
  for(let i=0;i<300;i++){
    stars.push({
      x:Math.random()*W,
      y:Math.random()*H,
      r:Math.random()*1.5+.2,
      brightness:Math.random()*.6+.2,
      speed:Math.random()*.3+.05,
      twinkleSpeed:Math.random()*3+1,
      twinkleOffset:Math.random()*Math.PI*2
    });
  }
  for(let i=0;i<8;i++){
    nebulae.push({
      x:Math.random()*W,y:Math.random()*H,
      r:Math.random()*200+100,
      color:['#7c3aed','#6366f1','#3b82f6','#8b5cf6','#a855f7','#ec4899'][Math.floor(Math.random()*6)],
      drift:Math.random()*.15-.075
    });
  }
}
initStars();

// Create planet particles
function createPlanetParticles(px,py,count){
  for(let i=0;i<count;i++){
    const angle=Math.random()*Math.PI*2;
    const dist=Math.random()*6+4;
    particles.push({
      x:px,y:py,vx:Math.cos(angle)*dist*.3,vy:Math.sin(angle)*dist*.3,
      life:1,decay:Math.random()*.015+.005,r:Math.random()*2+1,
      color:planetData.color||'#7c6aef'
    });
  }
}

// Draw functions
function drawStarsCtx(){
  starsCtx.clearRect(0,0,W,H);

  // Nebulae
  for(const n of nebulae){
    const g=starsCtx.createRadialGradient(n.x,n.y,0,n.x,n.y,n.r);
    const c=hexToRGBA(n.color,.06);
    g.addColorStop(0,c);g.addColorStop(1,'transparent');
    starsCtx.fillStyle=g;starsCtx.beginPath();starsCtx.arc(n.x,n.y,n.r,0,Math.PI*2);starsCtx.fill();
  }

  // Stars
  for(const s of stars){
    const twinkle=Math.sin(time*s.twinkleSpeed+s.twinkleOffset)*.3+.7;
    const alpha=s.brightness*twinkle;
    const pulse=Math.sin(time*2+s.twinkleOffset)*.1;

    if(s.r>1){
      const g=starsCtx.createRadialGradient(s.x,s.y,0,s.x,s.y,s.r*3);
      g.addColorStop(0,`rgba(200,210,255,${alpha*.3})`);
      g.addColorStop(1,'transparent');
      starsCtx.fillStyle=g;starsCtx.beginPath();starsCtx.arc(s.x,s.y,s.r*3,0,Math.PI*2);starsCtx.fill();
    }

    starsCtx.fillStyle=`rgba(220,225,255,${alpha})`;
    starsCtx.beginPath();starsCtx.arc(s.x,s.y,s.r*(1+pulse),0,Math.PI*2);starsCtx.fill();

    s.y+=s.speed;
    if(s.y>H+5){s.y=-5;s.x=Math.random()*W;}
  }
}

function drawAuroraCtx(){
  aurora.clearRect(0,0,W,H);
  const a=aurora.createLinearGradient(0,0,W,H);
  a.addColorStop(0,`rgba(124,106,239,${.02+Math.sin(time*.3)*.01})`);
  a.addColorStop(.5,`rgba(99,102,241,${.03+Math.sin(time*.5)*.015})`);
  a.addColorStop(1,`rgba(168,85,247,${.02+Math.cos(time*.4)*.01})`);
  aurora.fillStyle=a;
  aurora.beginPath();
  aurora.moveTo(0,0);
  for(let x=0;x<=W;x+=20){
    const y=H*.15+Math.sin(x*.003+time*.5)*H*.1+Math.sin(x*.007+time*.3)*H*.05;
    aurora.lineTo(x,y);
  }
  aurora.lineTo(W,H*.3);aurora.lineTo(0,H*.3);aurora.closePath();aurora.fill();
}

function drawViewCanvas(){
  const ctx=document.getElementById('viewCanvas').getContext('2d');
  ctx.clearRect(0,0,viewW,viewH);

  const cx=viewW/2,cy=viewH/2;

  if(viewMode==='free'){
    drawFreeSpace(ctx,cx,cy);
  } else if(viewMode==='planet'){
    drawPlanetView(ctx,cx,cy);
  } else if(viewMode==='ring'){
    drawRingSystem(ctx,cx,cy);
  } else if(viewMode==='star'){
    drawStarView(ctx,cx,cy);
  }

  drawParticles(ctx);
}

function drawFreeSpace(ctx,cx,cy){
  // Draw multiple small planets/stars floating
  const bodies=[
    {x:cx*.3,y:cy*.5,r:12,color:'#7c6aef',name:'Violet'},
    {x:cx*1.7,y:cy*.4,r:8,color:'#34d399',name:'Green'},
    {x:cx*.8,y:cy*1.4,r:20,color:'#fb923c',name:'Orange'},
    {x:cx*1.3,y:cy*1.1,r:6,color:'#f472b6',name:'Pink'},
    {x:cx*.2,y:cy*1.3,r:15,color:'#22d3ee',name:'Cyan'},
  ];

  for(const b of bodies){
    const px=b.x+Math.sin(time*.3+b.x)*15;
    const py=b.y+Math.cos(time*.25+b.y)*10;

    // Glow
    const g=ctx.createRadialGradient(px,py,0,px,py,b.r*4);
    g.addColorStop(0,hexToRGBA(b.color,.15));
    g.addColorStop(.5,hexToRGBA(b.color,.05));
    g.addColorStop(1,'transparent');
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(px,py,b.r*4,0,Math.PI*2);ctx.fill();

    // Body
    const bg=ctx.createRadialGradient(px-b.r*.3,py-b.r*.3,0,px,py,b.r);
    bg.addColorStop(0,'#fff');
    bg.addColorStop(.4,b.color);
    bg.addColorStop(1,hexToRGBA(b.color,.6));
    ctx.fillStyle=bg;ctx.beginPath();ctx.arc(px,py,b.r,0,Math.PI*2);ctx.fill();
  }
}

function drawPlanetView(ctx,cx,cy){
  const r=planetData.radius||40;

  // Background grid
  ctx.strokeStyle='rgba(255,255,255,.03)';ctx.lineWidth=1;
  for(let i=0;i<viewW;i+=40){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,viewH);ctx.stroke();}
  for(let i=0;i<viewH;i+=40){ctx.beginPath();ctx.moveTo(0,i);ctx.lineTo(viewW,i);ctx.stroke();}

  // Orbit path
  const orbitR=r*3+30;
  ctx.strokeStyle='rgba(255,255,255,.06)';ctx.lineWidth=1;ctx.setLineDash([4,4]);
  ctx.beginPath();ctx.arc(cx,cy,orbitR,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);

  // Rotating moons
  if(planetData.moons>0){
    for(let i=0;i<planetData.moons;i++){
      const angle=time*(.5+i*.2)+(i*Math.PI*2/planetData.moons);
      const mx=cx+Math.cos(angle)*orbitR;
      const my=cy+Math.sin(angle)*orbitR*.6;
      const mr=3+Math.random();
      ctx.fillStyle=hexToRGBA(planetData.color,.6);
      ctx.beginPath();ctx.arc(mx,my,mr,0,Math.PI*2);ctx.fill();

      const mg=ctx.createRadialGradient(mx,my,0,mx,my,mr*2);
      mg.addColorStop(0,hexToRGBA(planetData.color,.2));
      mg.addColorStop(1,'transparent');
      ctx.fillStyle=mg;ctx.beginPath();ctx.arc(mx,my,mr*2,0,Math.PI*2);ctx.fill();
    }
  }

  // Planet shadow
  const shadowG=ctx.createRadialGradient(cx+c*.2,cy+c*.2,0,cx,cy,r);
  shadowG.addColorStop(0,hexToRGBA('#000',.1));
  shadowG.addColorStop(1,'transparent');
  ctx.fillStyle=shadowG;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fill();

  // Planet body
  const pg=ctx.createRadialGradient(cx-r*.3,cy-r*.3,0,cx,cy,r);
  pg.addColorStop(0,'#fff');
  pg.addColorStop(.3,planetData.color);
  pg.addColorStop(1,hexToRGBA(planetData.color,.4));
  ctx.fillStyle=pg;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fill();

  // Atmosphere glow
  const ag=ctx.createRadialGradient(cx,cy,r-2,cx,cy,r+15);
  ag.addColorStop(0,hexToRGBA(planetData.color,.2));
  ag.addColorStop(1,'transparent');
  ctx.fillStyle=ag;ctx.beginPath();ctx.arc(cx,cy,r+15,0,Math.PI*2);ctx.fill();

  // Label
  ctx.fillStyle='rgba(255,255,255,.5)';ctx.font='12px Inter,sans-serif';ctx.textAlign='center';
  ctx.fillText(planetData.name,cx,cy+r+30);
}

function drawRingSystem(ctx,cx,cy){
  const r=30;

  // Rings
  for(let i=0;i<3;i++){
    const ringR=r+25+i*15;
    ctx.strokeStyle=hexToRGBA(planetData.color,.15-i*.04);
    ctx.lineWidth=8-i*2;
    ctx.beginPath();
    ctx.ellipse(cx,cy,ringR,ringR*.35,0.2+Math.sin(time*.1)*.05,0,Math.PI*2);
    ctx.stroke();
  }

  // Planet
  const pg=ctx.createRadialGradient(cx-r*.3,cy-r*.3,0,cx,cy,r);
  pg.addColorStop(0,'#fff');pg.addColorStop(.4,planetData.color);pg.addColorStop(1,hexToRGBA(planetData.color,.4));
  ctx.fillStyle=pg;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fill();

  // Front half of rings (over planet)
  for(let i=0;i<3;i++){
    const ringR=r+25+i*15;
    ctx.strokeStyle=hexToRGBA(planetData.color,.12-i*.03);
    ctx.lineWidth=8-i*2;
    ctx.beginPath();
    ctx.ellipse(cx,cy,ringR,ringR*.35,0.2+Math.sin(time*.1)*.05,0,Math.PI);
    ctx.stroke();
  }
}

function drawStarView(ctx,cx,cy){
  const baseR=25;

  // Corona rays
  for(let i=0;i<24;i++){
    const angle=(i/24)*Math.PI*2+time*.2;
    const len=baseR*2+Math.sin(time*3+i)*baseR;
    const px=cx+Math.cos(angle)*len;
    const py=cy+Math.sin(angle)*len;
    ctx.strokeStyle=hexToRGBA(planetData.color,.08+Math.sin(time*2+i)*.04);
    ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx+Math.cos(angle)*baseR,cy+Math.sin(angle)*baseR);
    ctx.lineTo(px,py);ctx.stroke();
  }

  // Multiple corona layers
  for(let i=3;i>=0;i--){
    const cr=baseR+i*12+Math.sin(time*2+i)*5;
    const g=ctx.createRadialGradient(cx,cy,baseR*.5,cx,cy,cr);
    g.addColorStop(0,hexToRGBA(planetData.color,.15));
    g.addColorStop(.5,hexToRGBA(planetData.color,.05));
    g.addColorStop(1,'transparent');
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(cx,cy,cr,0,Math.PI*2);ctx.fill();
  }

  // Star core
  const sg=ctx.createRadialGradient(cx,cy,0,cx,cy,baseR);
  sg.addColorStop(0,'#ffffff');
  sg.addColorStop(.3,planetData.color);
  sg.addColorStop(1,hexToRGBA(planetData.color,.6));
  ctx.fillStyle=sg;ctx.beginPath();ctx.arc(cx,cy,baseR,0,Math.PI*2);ctx.fill();
}

function drawParticles(ctx){
  for(let i=particles.length-1;i>=0;i--){
    const p=particles[i];
    p.x+=p.vx;p.y+=p.vy;
    p.life-=p.decay;
    if(p.life<=0){particles.splice(i,1);continue;}
    ctx.globalAlpha=p.life;
    ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.r*p.life,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
}

// Planet data
