// UI functions
function selectPlanet(idx){
  selectedPlanet=idx;
  const p=planets[idx];
  planetData={name:p.name,color:p.color,radius:p.radius,moons:p.moons,type:p.type};

  if(p.type==='Star'){
    viewMode='star';
    document.getElementById('viewTitle').textContent='⭐ '+p.name;
  } else if(p.name==='Saturn'||p.name==='Uranus'||p.name==='Neptune'){
    viewMode='ring';
    document.getElementById('viewTitle').textContent='🪐 '+p.name;
  } else {
    viewMode='planet';
    document.getElementById('viewTitle').textContent='🌍 '+p.name;
  }

  updateSidePanel();
  updateTabButtons();

  // Create particle burst
  const cv=document.getElementById('viewCanvas');
  const rect=cv.getBoundingClientRect();
  createPlanetParticles(rect.width/2,rect.height/2,30);
}

