              <div class="planet-icon" style="background:${p.color};border-radius:50%;width:36px;height:36px;display:flex;align-items:center;justify-content:center;font-size:1.2rem;
                background:radial-gradient(circle at 35% 35%,#fff 0%,${p.color} 40%,${hexToRGBA(p.color,.3)} 100%)">${planets[i].name==='Sun'?'☀':planets[i].name==='Earth'?'🌍':planets[i].name==='Jupiter'?'🟠':planets[i].name==='Saturn'?'💍':planets[i].name==='Mars'?'🔴':planets[i].name==='Venus'?'🟡':'·'}</div>
