          <div class="qs-label">Avg Temp</div>
        </div>
        <div class="qs">
          <div class="qs-val" style="color:${p.color}">${p.gravity}</div>
          <div class="qs-label">Gravity</div>
        </div>
        <div class="qs">
          <div class="qs-val" style="color:${p.color}">${p.diameter}</div>
          <div class="qs-label">Diameter</div>
        </div>
        <div class="qs">
          <div class="qs-val" style="color:${p.color}">${p.day}</div>
          <div class="qs-label">Day Length</div>
        </div>
      </div>
      <div class="detail-section" style="margin-top:1rem">
        <div class="stat-card">
          <div class="stat-label">Distance from Sun</div>
          <div class="stat-value" style="font-size:1.1rem">${p.dist}</div>
          <div class="stat-bar"><div class="stat-bar-fill" style="width:${barWidth}%;background:linear-gradient(90deg,${p.color},rgba(255,255,255,.3))"></div></div>
        </div>
        ${p.moons>0?`<div class="stat-card">
          <div class="stat-label">Known Moons</div>
          <div class="stat-value" style="font-size:1.1rem;color:${p.color}">${p.moons}</div>
        </div>`:''}
      </div>
      <div class="nav-row">
        <button class="nav-btn" onclick="navigatePlanet(-1)" ${selectedPlanet===0?'disabled':''}>&#8592; Prev</button>
        <span class="page-indicator">${selectedPlanet+1} / ${planets.length}</span>
        <button class="nav-btn primary" onclick="navigatePlanet(1)" ${selectedPlanet===planets.length-1?'disabled':''}>Next &#8594;</button>
