function navigatePlanet(dir){
  let next=selectedPlanet+dir;
  if(next<0||next>=planets.length)return;
  selectPlanet(next);
}

function updateTabButtons(){
  document.querySelectorAll('.tab').forEach(t=>{
    t.classList.toggle('active',t.dataset.tab===activeTab);
  });
}

function showFreeView(){
  selectedPlanet=null;
  viewMode='free';
  document.getElementById('viewTitle').textContent='🌌 Deep Space';
  updateSidePanel();
  updateTabButtons();
}

// Event listeners
document.querySelectorAll('.tab').forEach(tab=>{
  tab.addEventListener('click',()=>{
    activeTab=tab.dataset.tab;
    updateTabButtons();
    if(activeTab==='explore') showFreeView();
    updateSidePanel();
  });
});

// Mouse tracking for parallax
document.addEventListener('mousemove',e=>{
  mouse.x=(e.clientX/innerWidth-.5)*2;
  mouse.y=(e.clientY/innerHeight-.5)*2;
});

